A = (0,0);
B = A + dir(a);
C = A + dir(180 + a);
X = intersectionpoint(Circle(A,1),A--B);
Y = intersectionpoint(Circle(A,1),A--C);
O = (B*C)/(B + C);
D = extension(A, X, O, O + dir(90));
E = extension(A, Y, O, O + dir(270));

draw(X--Y--D--cycle);
draw(Circle(O,abs(O - X)));
draw(O--B);
draw(O--C);
draw(Circle(X,1));
draw(Circle(Y,1));
draw(O--A, dashed);

pair x = (1.3333,0.5);
label("$X$", X + x, S);

pair y = (-0.15,0.2);
label("$Y$", Y + y, W);

pair d = (0.03,0.32);
label("$D$", D + d, E);

